function applyWorkflowAction(action,requestId){
 const r=data.requests.find(x=>x.id===requestId);if(!r)return;const note=$('#workflow-note')?.value.trim()||'';
 const transitions={'receiver-sign':['Aguardando assinaturas','Solicitação encaminhada para assinatura dos responsáveis.'],'cedent-start':['Em análise pelo Cedente','Análise iniciada pelo órgão cedente.'],'cedent-approve':['Aguardando análise do Conecta','Solicitação aprovada pelo órgão Cedente e encaminhada para análise do Conecta.'],'cedent-reject':['Rejeitada pelo Cedente','Solicitação reprovada pelo Cedente.'],'viability-start':['Em avaliação de viabilidade','Encaminhada para avaliação de viabilidade.'],'viability-approve':['Aguardando disponibilização do conjunto de dados','Viabilidade aprovada. Aguardando disponibilização.'],'viability-reject':['Rejeitada pelo Cedente','Viabilidade reprovada pelo Cedente.'],'data-available':['Aguardando análise do Conecta','Disponibilização confirmada e compartilhamento aprovado.'],'conecta-start':['Em análise pelo Conecta','Análise iniciada pelo Conecta.'],'conecta-approve':['Deferido','Solicitação deferida pelo Conecta.'],'conecta-reject':['Rejeitada pelo Conecta','Solicitação reprovada pelo Conecta.']};
 if(action==='sign-dirti'||action==='sign-tech'){const key=action==='sign-dirti'?'dirTi':'respTech';r.signatures=r.signatures||{dirTi:false,respTech:false};r.signatures[key]=true;r.history=r.history||[];r.history.push({status:'Assinatura registrada (simulação)',date:today(),note:(key==='dirTi'?'Dirigente de TI':'Responsável Técnico')+' assinou. Não equivale à assinatura digital oficial.'});if(r.signatures.dirTi&&r.signatures.respTech){r.status='Aguardando análise do Cedente';r.history.push({status:r.status,date:today(),note:'Assinaturas concluídas. Encaminhada ao Cedente.'})}persist();viewRequest(r.id);toast('Assinatura registrada em modo de demonstração.','success');return}
 const next=transitions[action];if(!next)return;if(['cedent-reject','viability-reject','conecta-reject'].includes(action)&&!note){toast('Informe a justificativa para reprovar.','error');return}r.workflowNote=note;workflowHistory(r,next[0],next[1]+(note?' Justificativa: '+note:''));
}
